           <p class="error-message" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             inputmode="email"
             autocomplete="email"
             required
             aria-required="true"
             aria-describedby="email-error"
           >
           <p class="error-message" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             inputmode="tel"
             autocomplete="tel"
             aria-describedby="phone-helper phone-error"
           >
           <p class="helper-text" id="phone-helper">Optional. Use digits only, with an optional leading +, for example +14155550123.</p>
           <p class="error-message" id="phone-error" aria-live="polite"></p>
         </div>

         <div class="actions">
           <button type="submit">Submit request</button>
           <p class="form-status" id="form-status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const statusMessage = document.getElementById('form-status');

     const fieldConfigs = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Enter your full name.';
           }
           if (value.trim().length < 2) {
             return 'Full name must be at least 2 characters.';
           }
           return '';
         }
       },
       {
         input: document.getElementById('email'),
         error: document.getElementById('email-error'),
         validate(value) {
           const trimmedValue = value.trim();

           if (!trimmedValue) {
             return 'Enter your email address.';
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(trimmedValue)) {
             return 'Enter a valid email address.';
           }

           return '';
         }
       },
       {
         input: document.getElementById('phone'),
         error: document.getElementById('phone-error'),
         validate(value) {
           const trimmedValue = value.trim();

           if (!trimmedValue) {
             return '';
           }

           const phonePattern = /^\+?\d{7,15}$/;
           if (!phonePattern.test(trimmedValue)) {
             return 'Enter a valid phone number using 7 to 15 digits, with an optional leading +.';
           }

           return '';
         }
       }
     ];

     function updateFieldState(fieldConfig) {
       const message = fieldConfig.validate(fieldConfig.input.value);
       const fieldWrapper = fieldConfig.input.closest('.form-field');

       fieldConfig.error.textContent = message;
       fieldWrapper.classList.toggle('has-error', Boolean(message));

       if (message) {
         fieldConfig.input.setAttribute('aria-invalid', 'true');
       } else {
         fieldConfig.input.removeAttribute('aria-invalid');
       }

       return message;
     }

     fieldConfigs.forEach((fieldConfig) => {
       fieldConfig.input.addEventListener('blur', () => {
         updateFieldState(fieldConfig);
       });

       fieldConfig.input.addEventListener('input', () => {
         if (fieldConfig.input.getAttribute('aria-invalid') === 'true') {
           updateFieldState(fieldConfig);
         }

         statusMessage.textContent = '';
         statusMessage.dataset.state = '';
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const invalidFields = fieldConfigs.filter((fieldConfig) => updateFieldState(fieldConfig));

       if (invalidFields.length > 0) {
         statusMessage.textContent = 'Please correct the highlighted fields and try again.';
         statusMessage.dataset.state = 'error';
         invalidFields[0].input.focus();
         return;
       }

       statusMessage.textContent = 'Support request ready to send.';
       statusMessage.dataset.state = 'success';
')
